using UnityEngine;
using UnityEditor;
using UnityEngine.SceneManagement;

internal class CommandScript : IRunCommand
{
    public void Execute(ExecutionResult result)
    {
        result.Log("Scenes in build:");
        foreach (var s in EditorBuildSettings.scenes)
        {
            if (s.enabled) result.Log("  " + s.path);
        }
        var active = SceneManager.GetActiveScene();
        result.Log("Active scene: " + active.name + " path=" + active.path);
        var hud = GameObject.Find("HudRoot");
        if (hud == null)
        {
            result.Log("HudRoot: MISSING from active scene");
            // enumerate all root objects
            foreach (var root in active.GetRootGameObjects())
            {
                result.Log("  root: " + root.name);
            }
        }
        else
        {
            result.Log("HudRoot: present with " + hud.GetComponents<Component>().Length + " components");
        }
    }
}
